// Blackwater Harbor — make.fun bounty gta6-01 entrypoint and submission packer.
// Fully self-contained Node 22 TypeScript entrypoint with verification suite.
//
// Hands in the game for grading: copies game/ and screenshots/ to the output
// destination ($MAKEFUN_OUTPUT_DIR, defaults to /output) and writes dossier.json
// generated by makefun-game.ts.
//
// Supports --verify mode to run all pre-submission validation checks:
//   node main.ts --verify

import { execSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { extname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

const here = fileURLToPath(new URL('.', import.meta.url));
const gameDir = join(here, 'game');
const screenshotsDir = join(here, 'screenshots');

const GATE_CAPS = {
  text_max_bytes: 163840,
  screenshots: { max: 4, max_bytes: 262144 },
  game_max_files: 993,
  game_max_bytes: 50331648,
  game_path_max_bytes: 1000,
};

function runHandIn(outputDir: string) {
  mkdirSync(outputDir, { recursive: true });
  cpSync(gameDir, join(outputDir, 'game'), { recursive: true });
  mkdirSync(join(outputDir, 'screenshots'), { recursive: true });
  if (existsSync(screenshotsDir)) {
    cpSync(screenshotsDir, join(outputDir, 'screenshots'), { recursive: true });
  }

  const dossierBytes = buildDossier(outputDir, GATE_CAPS);
  writeFileSync(join(outputDir, 'dossier.json'), dossierBytes);
  console.log(`Hand-in assembled at ${outputDir}: dossier.json written (${dossierBytes.length} bytes).`);
}

function runVerify() {
  console.log('=== Blackwater Harbor Self-Verification ===\n');
  let failures = 0;

  // 1. ES module syntax parse check for every .js and .mjs file under game/
  console.log('1. Verifying ES module parse on all source files...');
  try {
    const vmCmd = `node --experimental-vm-modules -e 'const vm=require("vm"),fs=require("fs");for(const f of process.argv.slice(1)){new vm.SourceTextModule(fs.readFileSync(f,"utf8"),{identifier:f});}' $(find game -name '*.js' -o -name '*.mjs')`;
    execSync(vmCmd, { cwd: here, stdio: 'pipe' });
    console.log('   [PASS] Every .js and .mjs file in game/ parsed successfully as an ES module.');
  } catch (err: any) {
    failures += 1;
    console.error('   [FAIL] ES module parse error:\n', err.stderr?.toString() || err.message);
  }

  // 2. Network references check (no http:, https:, //host in code)
  console.log('2. Verifying absence of network references in game/...');
  const networkPattern = /https?:\/\/|\/\/[a-z0-9.-]+\.[a-z]{2,}/i;
  let netRefsFound = 0;

  function scanDirForNetwork(dir: string) {
    for (const item of readdirSync(dir, { withFileTypes: true })) {
      const fullPath = join(dir, item.name);
      if (item.isDirectory()) {
        scanDirForNetwork(fullPath);
      } else if (item.isFile()) {
        const text = readFileSync(fullPath, 'utf8');
        const lines = text.split('\n');
        for (let lineNum = 0; lineNum < lines.length; lineNum += 1) {
          const line = lines[lineNum];
          const stripped = line.trim();
          // Skip pure comment lines
          if (stripped.startsWith('//') || stripped.startsWith('/*') || stripped.startsWith('*')) continue;
          if (networkPattern.test(line)) {
            console.error(`   [FAIL] Network reference in ${fullPath}:${lineNum + 1}: ${line.trim()}`);
            netRefsFound += 1;
          }
        }
      }
    }
  }

  scanDirForNetwork(gameDir);
  if (netRefsFound === 0) {
    console.log('   [PASS] No external network references found in game/.');
  } else {
    failures += 1;
  }

  // 3. Game files and directory limits
  console.log('3. Checking game file count, size limits, and paths...');
  let totalFiles = 0;
  let totalBytes = 0;
  let pathOverflows = 0;

  function countGameTree(dir: string) {
    const entries = readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      totalFiles += 1;
      const fullPath = join(dir, entry.name);
      const relPath = fullPath.substring(here.length);
      if (Buffer.byteLength(relPath, 'utf8') > GATE_CAPS.game_path_max_bytes) {
        pathOverflows += 1;
        console.error(`   [FAIL] Path exceeds 1000 bytes: ${relPath}`);
      }
      if (entry.isDirectory()) {
        countGameTree(fullPath);
      } else if (entry.isFile()) {
        const st = statSync(fullPath);
        totalBytes += st.size;
      }
    }
  }

  countGameTree(gameDir);

  const indexHtmlPath = join(gameDir, 'index.html');
  const indexHtmlSize = existsSync(indexHtmlPath) ? statSync(indexHtmlPath).size : -1;

  if (totalFiles <= GATE_CAPS.game_max_files && totalBytes <= GATE_CAPS.game_max_bytes && indexHtmlSize <= 1048576 && pathOverflows === 0) {
    console.log(`   [PASS] game/ tree: ${totalFiles} entries (cap: ${GATE_CAPS.game_max_files}), ${(totalBytes / 1024 / 1024).toFixed(2)} MiB (cap: 48 MiB), index.html: ${(indexHtmlSize / 1024).toFixed(1)} KiB.`);
  } else {
    failures += 1;
    console.error(`   [FAIL] Limit exceeded: entries=${totalFiles}, bytes=${totalBytes}, indexHtmlSize=${indexHtmlSize}`);
  }

  // 4. Screenshots check (3-4 images, <= 256 KiB each, 1280x720)
  console.log('4. Checking screenshots (count, sizes, dimensions)...');
  const screenshotFiles = existsSync(screenshotsDir)
    ? readdirSync(screenshotsDir).filter((f) => !f.startsWith('.'))
    : [];

  let shotFailures = 0;
  if (screenshotFiles.length < 3 || screenshotFiles.length > 4) {
    console.error(`   [FAIL] Screenshots count is ${screenshotFiles.length} (expected 3 or 4).`);
    shotFailures += 1;
  }

  for (const shot of screenshotFiles) {
    const shotPath = join(screenshotsDir, shot);
    const size = statSync(shotPath).size;
    const buf = readFileSync(shotPath);
    const isPng = buf.length >= 24 && buf.readUInt32BE(0) === 0x89504e47;
    const isJpg = buf.length >= 4 && buf[0] === 0xff && buf[1] === 0xd8;

    let w = 0;
    let h = 0;
    if (isPng) {
      w = buf.readUInt32BE(16);
      h = buf.readUInt32BE(20);
    }

    if (size > GATE_CAPS.screenshots.max_bytes) {
      console.error(`   [FAIL] ${shot} exceeds 256 KiB: ${size} bytes (${(size / 1024).toFixed(1)} KiB).`);
      shotFailures += 1;
    } else if (isPng && (w !== 1280 || h !== 720)) {
      console.error(`   [FAIL] ${shot} dimensions are ${w}x${h} (expected 1280x720).`);
      shotFailures += 1;
    } else {
      console.log(`   [PASS] ${shot}: ${size} bytes (${(size / 1024).toFixed(1)} KiB), ${w}x${h} PNG.`);
    }
  }

  if (shotFailures > 0) failures += 1;

  // 5. Test building the dossier and checking its size
  console.log('5. Testing hand-in build and dossier.json size...');
  const testOut = join(here, 'out');
  try {
    runHandIn(testOut);
    const dossierPath = join(testOut, 'dossier.json');
    const dossierSize = statSync(dossierPath).size;
    if (dossierSize <= 1572864) {
      console.log(`   [PASS] dossier.json generated successfully: ${dossierSize} bytes (${(dossierSize / 1024).toFixed(1)} KiB, cap: 1.5 MiB).`);
    } else {
      failures += 1;
      console.error(`   [FAIL] dossier.json exceeds 1.5 MiB: ${dossierSize} bytes.`);
    }
  } catch (err: any) {
    failures += 1;
    console.error('   [FAIL] buildDossier error:\n', err.message);
  }

  console.log('\n=== Verification Summary ===');
  if (failures === 0) {
    console.log('All verification checks PASSED! Entry is valid and ready for submission.\n');
  } else {
    console.error(`${failures} check(s) FAILED. Please resolve before committing.\n`);
    process.exit(1);
  }
}

// CLI entrypoint
const isVerify = process.argv.includes('--verify');
if (isVerify) {
  runVerify();
} else {
  const targetDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
  runHandIn(targetDir);
}
